package com.krdevops.springai.model.contract;
public record PipelineErrorResponse(String code,String message,String operationId){public PipelineErrorResponse{if(code==null||!code.matches("[A-Z][A-Z0-9_]{2,63}")||message==null||message.isBlank()||message.length()>4096||(operationId!=null&&!operationId.isBlank()&&!operationId.matches("[A-Za-z0-9._:-]{1,128}")))throw new IllegalArgumentException("오류 응답 필수값이 올바르지 않습니다.");} public boolean hasOperationId(){return operationId!=null&&!operationId.isBlank();} public String safeSummary(){return hasOperationId()?code+"["+operationId+"]":code;} public java.util.Map<String,String> safeLogFields(){var fields=new java.util.LinkedHashMap<String,String>(); fields.put("code",code); if(hasOperationId())fields.put("operationId",operationId); return java.util.Map.copyOf(fields);} public PipelineErrorResponse withOperationId(String id){return new PipelineErrorResponse(code,message,id);} public static PipelineErrorResponse forOperation(String code,String message,String operationId){return new PipelineErrorResponse(code,message,operationId==null?"":operationId);}}
